using System;using System.Linq;using System.Xml;using BeamScheduleFormatter;
class OpeningHardwareLinkTests {
 static int checks;static void Check(bool v,string m){if(!v)throw new Exception(m);checks++;}static void Bad(Action a,string m){bool bad=false;try{a();}catch{bad=true;}Check(bad,m);}
 static void Main(){Check(OpeningHardware.PerLeaf(1.524,.9)==2,"Short leaf count");Check(OpeningHardware.PerLeaf(1.524001,.9)==3,"60 inch transition");Check(OpeningHardware.PerLeaf(2.286,.9)==3,"90 inch boundary");Check(OpeningHardware.PerLeaf(2.286001,.9)==4,"Tall leaf count");Check(OpeningHardware.PerLeaf(2.1,1.0)==4,"Wide leaf allowance");var door=new OpeningItem{Id="D1",Description="Door",Material="Wood",Kind="Door",Width=1.9,Height=2.15,Quantity=3,JambDepth=.15,JambThickness=.05,LeafThickness=.045,Faces=2,Leaves=2};door.Validate();Check(door.EffectiveThickness==.045&&door.Hinges==18&&door.Locks==3,"Double door hinge/lock quantities");door.Operation="Sliding";Check(door.Hinges==0&&door.Locks==3,"Sliding counts");door.Operation="Fixed";Check(door.Hinges==0&&door.Locks==0,"Fixed panel counts");door.Operation="Swing";var links=new[]{new OpeningLink{Wall="W1",Schedule="D1",Quantity=1},new OpeningLink{Wall="W2",Schedule="d1",Quantity=2}};var resolved=OpeningLinks.Resolve(new[]{door},links);Check(resolved.Count==2&&resolved.Sum(o=>o.Area)==door.Area,"Split schedule assignments / source quantity");door.Wall="W1";Check(OpeningLinks.Resolve(new[]{door},links).Count==2,"Legacy Wall ID double counted with explicit links");Bad(()=>OpeningLinks.Resolve(new[]{door},new[]{links[0],links[0]}),"Duplicate wall-schedule accepted");Bad(()=>OpeningLinks.Resolve(new[]{door},new[]{new OpeningLink{Wall="W1",Schedule="D1",Quantity=4}}),"Over-assignment accepted");Bad(()=>OpeningLinks.Resolve(new[]{door},new[]{new OpeningLink{Wall="W1",Schedule="Missing",Quantity=1}}),"Unknown schedule accepted");var doc=new XmlDocument();doc.LoadXml("<ProgramOfWorks/>");OpeningLinks.Write(doc.DocumentElement,links);Check(OpeningLinks.Read(doc.DocumentElement).Sum(l=>l.Quantity)==3,"Schedule links round trip");var w=new WallItem{Id="W1",Description="CHB",Length=4,Height=3,Quantity=1,BlockWidth=.4,BlockHeight=.2,ThicknessMm=100};long a=w.Blocks(resolved);w.ThicknessMm=150;Check(w.Blocks(resolved)==a,"Thickness changed face-based block count");w.EnteredArea=30;Check(Math.Abs(w.Net(resolved)-(30-resolved.Where(o=>o.Wall=="W1").Sum(o=>o.Area)))<1e-8,"Direct gross area not used");w.EnteredArea=-1;Bad(()=>w.Validate(),"Negative direct area accepted");w.EnteredArea=30;w.ThicknessMm=200;Bad(()=>w.Validate(),"Unsupported 200mm accepted");w.ThicknessMm=0;Bad(()=>w.Validate(),"Missing CHB thickness accepted");Console.WriteLine("PASS: "+checks+" automatic hardware, 45mm door basis, opening-schedule assignments, quantity bounds and CHB thickness checks.");}
}
